package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class ThreeStepWholeContextsTest {
 @Test public void normalMillionRangeChoosesContextFamiliesBeforeConditions(){
  assertEquals(432780662L,ThreeStepWholeContexts.count(1000000));Random random=new Random(346);CurriculumLimits limits=new CurriculumLimits("maxGiven=1000000;maxResult=1000000;nonnegative=true");Map<String,Integer>recent=new HashMap<>();int[]counts=new int[4];
  for(int i=0;i<800;i++){Question q=ThreeStepWholeContexts.next(random,limits,recent);assertTrue(limits.allows(q));assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),i);counts[ThreeStepWholeContexts.read(q).family()]++;}
  for(int count:counts)assertTrue(Arrays.toString(counts),count>=120&&count<=280);
 }
 @Test public void partialFamiliesAndFilteredPoolsRemainFreshThenGloballyOldest(){
  for(int maximum:new int[]{3,4,5,12}){
   CurriculumLimits limits=new CurriculumLimits("maxGiven="+maximum+";maxResult="+maximum+";nonnegative=true"+(maximum==12?";minGiven=2":""));Set<String>allowed=new HashSet<>();for(long i=0;i<ThreeStepWholeContexts.count(maximum);i++){Question q=ThreeStepWholeContexts.indexed(i,maximum);if(limits.allows(q))allowed.add(q.signature());}assertFalse(allowed.isEmpty());
   Random random=new Random(346);Map<String,Integer>recent=new LinkedHashMap<>();for(int i=0;i<allowed.size();i++){Question q=ThreeStepWholeContexts.next(random,limits,recent);assertTrue(allowed.contains(q.signature()));assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),i);}assertEquals(allowed,recent.keySet());assertEquals(0,(int)recent.get(ThreeStepWholeContexts.next(random,limits,recent).signature()));
  }
 }
 @Test public void fourStoriesDeriveThreeDependentOperationsFromPublicText(){int[][]data={{0,12,3,8,5},{1,20,10,6,4},{2,50,10,5,3},{3,12,3,12,4}};long[][]expected={{36,44,39},{30,24,6},{40,8,11},{36,48,12}};String[]expressions={"((12*3)+8)-5","((20+10)-6)/4","((50-10)/5)+3","((12*3)+12)/4"};for(int i=0;i<4;i++){int[]v=data[i];Question q=ThreeStepWholeContexts.make(v[0],v[1],v[2],v[3],v[4]);q.expression="1/0";q.answers=new String[]{"999"};assertArrayEquals(expected[i],ThreeStepWholeContexts.read(q).intermediates());assertEquals(expressions[i],ThreeStepWholeContexts.workQuestion(q).expression);assertTrue(ThreeStepWholeContexts.check(q,List.of(""+expected[i][2])).correct());assertFalse(ThreeStepWholeContexts.check(q,List.of(""+expected[i][1])).correct());assertEquals("number",q.kind);assertTrue(q.stepSupport);}}
 @Test public void zeroLargeAndInvalidDivisionHaveRealQuantityBounds(){for(int f=0;f<4;f++){Question q=switch(f){case 0->ThreeStepWholeContexts.make(f,0,10,0,0);case 1->ThreeStepWholeContexts.make(f,0,0,0,1);case 2->ThreeStepWholeContexts.make(f,0,0,1,0);default->ThreeStepWholeContexts.make(f,0,1,0,1);};assertTrue(ThreeStepWholeContexts.check(q,List.of("0")).correct());}assertEquals(999999,ThreeStepWholeContexts.read(ThreeStepWholeContexts.make(0,1000,1000,0,1)).result());assertEquals(1000000,ThreeStepWholeContexts.read(ThreeStepWholeContexts.make(3,1000,1000,0,1)).result());for(int[]v:new int[][]{{1,10,1,0,3},{1,1,0,0,0},{2,10,0,3,0},{2,10,0,0,0},{0,1000000,2,0,0},{3,1000000,1,1,1},{0,0,0,0,1}})try{ThreeStepWholeContexts.make(v[0],v[1],v[2],v[3],v[4]);fail(Arrays.toString(v));}catch(IllegalArgumentException expected){}Question q=ThreeStepWholeContexts.make(1,20,10,6,4);q.prompt=q.prompt.replace("4名","0名").replace("4명","0명");assertNull(ThreeStepWholeContexts.read(q));}
 @Test public void indexedVariableTeachingDomainIsUniqueFreshThenOldest(){int max=12;Set<String>independent=new HashSet<>();Set<Integer>families=new HashSet<>();
  for(int a=0;a<=max;a++)for(int b=1;b<=max;b++)for(int c=1;c<=max;c++)for(int d=1;d<=max;d++)for(int f=0;f<4;f++){
   boolean selected=switch(f){case 0->a>=1&&b>=2&&b<=10&&c<=9&&d<=c;case 1->b<=9&&c<=9&&d>=2&&d<=10;case 2->b<=9&&c>=2&&c<=10&&d<=9;default->a>=1&&d>=2&&d<=10&&b%d==0&&b/d>=2&&b/d<=10&&c%d==0&&c/d>=1&&c/d<=9;};if(!selected)continue;
   long x=f==0||f==3?(long)a*b:f==1?a+b:a-b;long y=f==0||f==3?x+c:f==1?x-c:c==0?-1:x/c;long z=f==0?y-d:f==2?y+d:d==0?-1:y/d;
   if(x<0||x>max||y<0||y>max||z<0||z>max||f==2&&x%c!=0||(f==1||f==3)&&(y%d!=0||z<1)||f==2&&y<1)continue;
   independent.add(ThreeStepWholeContexts.make(f,a,b,c,d).signature());families.add(f);
  }
  assertEquals(Set.of(0,1,2,3),families);assertEquals(independent.size(),ThreeStepWholeContexts.count(max));Set<String>indexed=new HashSet<>();for(long i=0;i<ThreeStepWholeContexts.count(max);i++)assertTrue(indexed.add(ThreeStepWholeContexts.indexed(i,max).signature()));assertEquals(independent,indexed);
  Map<String,Integer>recent=new LinkedHashMap<>();CurriculumLimits limits=new CurriculumLimits("maxGiven=12;maxResult=12;nonnegative=true");Random r=new Random(2);for(int i=0;i<independent.size();i++){Question q=ThreeStepWholeContexts.next(r,limits,recent);assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),i);}assertEquals(0,(int)recent.get(ThreeStepWholeContexts.next(r,limits,recent).signature()));assertEquals(0,ThreeStepWholeContexts.count(0));assertTrue(ThreeStepWholeContexts.count(1000000)>1000000);Set<String>normal=new HashSet<>();CurriculumLimits large=new CurriculumLimits("maxGiven=1000000;maxResult=1000000;nonnegative=true");Map<String,Integer>history=new HashMap<>();for(int i=0;i<100;i++){Question q=ThreeStepWholeContexts.next(r,large,history);assertTrue(normal.add(q.signature()));history.put(q.signature(),i);ThreeStepWholeContexts.Givens v=ThreeStepWholeContexts.read(q);for(long value:v.intermediates())assertTrue(value>=0&&value<=1000000);}
 }
 @Test public void nineHelpFramesRequireChoicesAndStudentIntermediatesWithoutTransfer(){Question q=ThreeStepWholeContexts.make(2,50,10,5,3);q.answers=new String[]{"poison"};q.expression="poison";ThreeStepWholeContexts.attach(q);assertFalse(q.studyGuide.transfer);assertEquals(9,q.studyGuide.frames.size());List<String>expected=List.of("-","mental","40","/","mental","8","+","mental","11");for(int i=0;i<9;i++){assertTrue(i%3==1?q.studyGuide.frames.get(i).acceptedChoices.contains(expected.get(i)):q.studyGuide.frames.get(i).expected.equals(expected.get(i)));if(i%3==1)assertTrue(q.studyGuide.frames.get(i).acceptedChoices.contains("written"));if(i%3==2)assertEquals("",q.studyGuide.frames.get(i).after);}assertEquals("three-step-whole-contexts-v1",q.studyGuide.teachingVersion);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(9,h.size());assertFalse(h.canTransfer());HelpPlan.Draft draft=h.restore(null,q.id);assertTrue(draft.entries.stream().allMatch(String::isEmpty));draft.entries=new ArrayList<>(expected);draft.stage=9;HelpPlan.Draft saved=h.restore(draft.copy(),q.id);assertEquals(9,saved.stage);assertEquals(expected,saved.entries.subList(0,9));for(String s:List.of("","1+10","-11","11.0"))assertEquals(Checker.Status.INPUT_NEEDED,ThreeStepWholeContexts.check(q,List.of(s)).status);}
}
